#!/usr/bin/env bash
# Full study for one molecule.  Everything is generated by the code from real Hamiltonians and a
# real-device-derived noise model; nothing is synthetic.  Adjust MOL / shot budgets to your compute.
set -euo pipefail
MOL=${1:-H2}
ANS=${2:-uccsd}
python calibration.py --fake FakeSherbrooke --out data/calibration.json       # once (or use --backend <your device>)
python -m pytest tests -q                                                       # software self-checks
for S in 10000 100000 1000000 10000000; do
  python run_experiment.py --molecule "$MOL" --ansatz "$ANS" --shots $S --reps 500 --hier-reps 20
  python analyze.py results/raw_${MOL}_r*_${ANS}_S${S}_x1_l1_uniform.npz --hier-reps 20
done
# Neyman allocation across noise levels at the same total budget
python run_experiment.py --molecule "$MOL" --ansatz "$ANS" --shots 1000000 --reps 500 --lambda-alloc neyman
python analyze.py results/raw_${MOL}_r*_${ANS}_S1000000_x1_l1_neyman.npz
python noise_sweep.py --molecule "$MOL" --ansatz "$ANS"
python make_figures.py --molecule "$MOL" --ansatz "$ANS"
